code.cpp:
class Solution {
public:
    bool isGood(vector<int>& nums) {
        int n = *max_element(nums.begin(), nums.end());
        if ((int)nums.size() != n + 1) return false;
        int cnt[201] = {0};
        for (int x : nums) cnt[x]++;
        for (int i = 1; i < n; i++) {
            if (cnt[i] != 1) return false;
        }
        return cnt[n] == 2;
    }
};
